    else:
        first_failing_seed = next(seed for seed, r in zip(seeds, results) if not r["conjecture_holds"])
        print(f"RESULT: FALSIFIED counterexample=\"UPC(F)=1 exceeded 0.20 by ≥3σ\" first_failing_seed={first_failing_seed}")
